import {balanceFor} from './balance.js?v=1.2';
// Pure, deterministic simulation. No DOM or rendering dependencies.
export const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function seeded(seed){let s=seed>>>0;return()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};}
export const REGIONS=[
 {name:'Green frontier',ground:'#659564',road:'#cab887',sky:'#b9dfdb',fog:'#bfd7bb',leaf:'#32694d',accent:'#e5bd67'},
 {name:'Ruined kingdom',ground:'#797d68',road:'#afa58c',sky:'#ccd3d0',fog:'#b5b9ab',leaf:'#566c51',accent:'#f5cb86'},
 {name:'Haunted forest',ground:'#3d625b',road:'#778076',sky:'#769a9f',fog:'#73938e',leaf:'#214c4b',accent:'#adf2d1'},
 {name:'Frozen pass',ground:'#cadde0',road:'#a3bac6',sky:'#d2e6ee',fog:'#c7dce6',leaf:'#607f91',accent:'#9de8ff'},
 {name:'Volcanic fortress',ground:'#4e4b51',road:'#776763',sky:'#bf9390',fog:'#ab8582',leaf:'#3e3b48',accent:'#ffb278'},
 {name:'Imperial stronghold',ground:'#7c927a',road:'#b9b3a3',sky:'#c5d8e0',fog:'#bdcbbf',leaf:'#425c68',accent:'#ffd77a'}];
export const BOSSES=[
 {name:'Brambleback',kind:'ogre',title:'THE FRONTIER COLOSSUS',pattern:'slam',hint:'His fist marks your lane. Move before it falls.'},
 {name:'The Hollow Regent',kind:'knight',title:'KING OF THE FALLEN',pattern:'cross',hint:'His shield turns arrows. Align with the golden heart.'},
 {name:'Morrowwing',kind:'wyvern',title:'SHADOW OF THE WOOD',pattern:'breath',hint:'A sweeping breath leaves one safe flank.'},
 {name:'Skarn, the Pale',kind:'golem',title:'THE WINTER HEART',pattern:'ice',hint:'Ice seals two lanes. Break his exposed crystal.'},
 {name:'Cindermaw',kind:'dragon',title:'THE ASHEN TYRANT',pattern:'fire',hint:'Dodge the fire pools. Strike as his jaw opens.'},
 {name:'Emperor Veyr',kind:'emperor',title:'THE LAST CROWN',pattern:'imperial',hint:'He calls his guard. Save a volley for the reinforcements.'}];
const titles=['The banner rises','Brambleback’s crossing','Road of broken crowns','The Hollow Regent','Whispers in the green','Wings over Blackwood','Snowblind approach','Heart of the glacier','The ember road','At the dragon’s gate','The gilded legion','Fall of the last crown'];
const mechanics=['Choose the green recruitment gates.','Dodge the colossus’s marked strikes.','Shield bearers resist arrows; charge breaks armor.','Find the Regent’s moving weak point.','Ambushes emerge from the trees.','Flying creatures weave across your line of fire.','Ice forces your army into narrow lanes.','Shatter the frost heart between ice strikes.','Siege engines bombard the road.','Watch the dragon’s jaw before its breath.','Cavalry charges between branching routes.','Defeat Veyr and reclaim the crown.'];
export const STAGES=titles.map((name,i)=>({id:i,name,region:Math.floor(i/2),boss:i%2===1?Math.floor(i/2):null,length:300+i*7,brief:mechanics[i],seed:1931+i*811}));
export const HEROES=[{id:'rowan',name:'Rowan',title:'The Banner Knight',unlock:0,description:'+5 starting soldiers · stronger charge',color:'#4dbee0'}, {id:'lyra',name:'Lyra',title:'The Green Arrow',unlock:3,description:'30% faster volleys · archer warband',color:'#75d4a4'}, {id:'sol',name:'Sol',title:'The Dawncaller',unlock:6,description:'Double magical damage · spellguard',color:'#dcb0fc'}, {id:'astrid',name:'Astrid',title:'The Iron Valkyrie',unlock:9,description:'25% damage resistance · cavalry',color:'#ffcd79'}];
export const BUILDINGS={barracks:{name:'Barracks',icon:'⚑',detail:'+3 starting troops, +1 per recruitment',base:70},forge:{name:'Forge',icon:'⚒',detail:'+12% damage, +4% attack speed',base:85},academy:{name:'Academy',icon:'✧',detail:'−6% ability cooldown, +10% spell power',base:90},treasury:{name:'Treasury',icon:'◈',detail:'+15% gold from every battle',base:65},fortress:{name:'Fortress',icon:'♜',detail:'−6% incoming damage',base:80}};
export function freshSave(){return {version:1,gold:150,unlocked:0,cleared:[],hero:'rowan',upgrades:{barracks:0,forge:0,academy:0,treasury:0,fortress:0},settings:{sound:true,motion:true,quality:'auto',difficulty:'standard'},best:{endless:0,bossrush:0,daily:0},heroXP:0};}
export function loadSave(storage){try{const raw=JSON.parse(storage.getItem('crownmarch-v1'));if(!raw||raw.version!==1)return freshSave();const s=freshSave();s.gold=clamp(Math.floor(+raw.gold||0),0,1e8);s.unlocked=clamp(Math.floor(+raw.unlocked||0),0,11);s.cleared=[...new Set((raw.cleared||[]).filter(n=>Number.isInteger(n)&&n>=0&&n<12))];for(const k of Object.keys(s.upgrades))s.upgrades[k]=clamp(Math.floor(+raw.upgrades?.[k]||0),0,10);for(const k of Object.keys(s.best))s.best[k]=clamp(Math.floor(+raw.best?.[k]||0),0,1e9);s.hero=HEROES.some(h=>h.id===raw.hero&&h.unlock<=s.unlocked)?raw.hero:'rowan';s.heroXP=clamp(+raw.heroXP||0,0,1e9);s.settings={difficulty:['relaxed','standard','veteran'].includes(raw.settings?.difficulty)?raw.settings.difficulty:'standard',sound:raw.settings?.sound!==false,motion:raw.settings?.motion!==false,quality:['auto','low','high'].includes(raw.settings?.quality)?raw.settings.quality:'auto'};return s;}catch{return freshSave();}}
export function persist(s,storage){try{storage.setItem('crownmarch-v1',JSON.stringify(s));return true;}catch{return false;}}
export const upgradeCost=(s,k)=>Math.floor(BUILDINGS[k].base*Math.pow(1.65,s.upgrades[k]));
export function upgrade(s,k){if(!BUILDINGS[k]||s.upgrades[k]>=10)return false;const cost=upgradeCost(s,k);if(s.gold<cost)return false;s.gold-=cost;s.upgrades[k]++;return true;}
export function applyGate(n,op,value){return clamp(Math.floor(op==='+'?n+value:op==='−'?n-value:op==='×'?n*value:n/value),1,120);}
export const dailySeed=(date=new Date())=>Number(date.toISOString().slice(0,10).replaceAll('-',''));
export const LARGE_ENEMIES=new Set(['brute','ogre','champion']);
