 ability(key){if(this.status!=='playing'||!(key in this.abilities)||this.abilities[key]>0)return false;const cooldown={volley:7,shield:12,charge:10,magic:13}[key];this.abilities[key]=cooldown*Math.max(.4,1-this.up.academy*.06)*(this.hero==='lyra'&&key==='volley'?.7:1);if(key==='shield')this.shield=5;if(key==='charge'){this.charge=3;for(const e of this.entities)if(Math.abs(e.x-this.x)<4&&e.z>-30&&!['gate','treasure'].includes(e.type))this.hit(e,this.hero==='rowan'?80:55);if(this.boss&&Math.abs(this.x-this.boss.weakX)<3)this.hit(this.boss,45,true);}if(key==='volley'||key==='magic'){const dmg=(key==='magic'?85:48)*(1+this.up.academy*.1)*(this.hero==='sol'&&key==='magic'?2:1);for(const e of this.entities)if(!['gate','treasure'].includes(e.type))this.hit(e,dmg);if(this.boss)this.hit(this.boss,dmg,key==='magic'||Math.abs(this.x-this.boss.weakX)<2);}this.emit('ability',{key,x:this.x,z:-10});return true;}
 mark(x,width,delay=1.7,damage=5,kind='strike'){this.hazards.push({id:++this.id,x,width,delay,damage,kind,z:2,life:.6,triggered:false});}
 bossStep(dt){const b=this.boss;if(!b)return;b.age+=dt;b.flash=Math.max(0,b.flash-dt);b.phase=b.hp<b.maxHp*.33?3:b.hp<b.maxHp*.68?2:1;b.x=Math.sin(b.age*.5)*2.3;b.weakX=b.x+Math.sin(b.age*1.2)*1.3;b.open=Math.sin(b.age*1.7)>-.3;b.attack-=dt;if(b.attack<=0){b.attack=(b.phase===3?2.7:4.3);const damage=3+b.phase*1.2;if(b.pattern==='slam')this.enemyMark(this.x,3,1.7,damage,'slam');if(b.pattern==='cross'){this.enemyMark(-4,3,1.7,damage,'slash');this.enemyMark(4,3,1.7,damage,'slash');if(b.phase===3)this.enemyMark(0,2,2.5,damage,'slash');}if(b.pattern==='breath'||b.pattern==='fire'){const safe=b.age%8<4?-1:1;this.enemyMark(-safe*2.7,8,2.1,damage,b.pattern==='fire'?'fire':'poison');}if(b.pattern==='ice'){for(const x of [-4,0,4].filter((_,i)=>i!==Math.floor(b.age)%3))this.enemyMark(x,2.6,1.8,damage,'ice');}if(b.pattern==='imperial'){this.enemyMark(this.x,3,1.5,damage,'lightning');if(b.phase>1){this.add('shield',-4,-27);this.add('cavalry',4,-30);}}this.emit('telegraph',{name:b.name,phase:b.phase});}if(b.phase===3&&this.elapsedBoss<3){this.elapsedBoss=3;this.emit('enrage');}}
 finish(){if(this.status!=='playing')return;this.status='victory';this.score+=Math.floor(this.army*10);this.emit('victory');}
